576							<input type="email" id="email" name="email" autocomplete="email" inputmode="email" spellcheck="false" autocapitalize="none" required aria-describedby="email-help">
577							<span id="email-error" class="error-message"></span>
578							<small id="email-help" class="form-hint">For example, name@example.com</small>
579						</div>
